import React, {useState} from 'react';
import {Link} from 'react-router-dom';
import {Alert, Button, CircularProgress, MenuItem, Stack, Tab, Tabs, TextField, Typography} from '@mui/material';
import {MainDiv, PageTitle, Surface} from '../../ui/commonStyled/commonStyled';
import {getApiErrorMessage} from '../../api/errors';
import CompanyPicker from './CompanyPicker';
import {DataDetails} from './CompanyCard';
import {DaDataOperation, useCounterpartyCapabilitiesQuery, useExecuteDaDataMutation} from './counterpartiesApi';

export function toolBody(operation: string, query: string, count: number, lat: string, lon: string, date: string): unknown {
    if (operation === 'clean') return {structure: ['NAME','BIRTHDATE','ADDRESS','PHONE','EMAIL','PASSPORT'], data: [query.split('|').map(value => value.trim())]};
    if (operation.startsWith('clean/')) return query.split('\n').map(value => value.trim()).filter(Boolean);
    if (operation.startsWith('geolocate/')) return {lat: Number(lat), lon: Number(lon), count, radius_meters: 1000};
    if (operation === 'iplocate/address') return {ip: query.trim()};
    if (operation === 'stat/daily') return date ? {date} : {};
    if (['version','profile/balance'].includes(operation)) return {};
    return {query: query.trim(), count};
}
function Tools({operations, canClean, configured}: {operations: DaDataOperation[]; canClean: boolean; configured: boolean}) {
    const [operation, setOperation] = useState('suggest/bank'); const [query, setQuery] = useState('');
    const [count, setCount] = useState(10); const [lat, setLat] = useState(''); const [lon, setLon] = useState(''); const [date, setDate] = useState('');
    const [execute, state] = useExecuteDaDataMutation(); const [result, setResult] = useState<unknown>(); const [error, setError] = useState('');
    const selected = operations.find(item => item.id === operation); const geo = operation.startsWith('geolocate/');
    const profile = selected?.service === 'profile'; const clean = selected?.service === 'cleaner';
    const validGeo = lat.trim() !== '' && lon.trim() !== '' && Number.isFinite(Number(lat)) && Number.isFinite(Number(lon)) && Math.abs(Number(lat)) <= 90 && Math.abs(Number(lon)) <= 180;
    const needsCount = !clean && !profile && operation !== 'iplocate/address';
    const validCount = Number.isInteger(count) && count >= 1 && count <= (operation === 'findById/party' ? 300 : 20);
    async function run() {
        setError(''); setResult(undefined);
        try {setResult(await execute({operation, body: toolBody(operation, query, count, lat, lon, date)}).unwrap());}
        catch (failure) {setError(getApiErrorMessage(failure, 'Не удалось выполнить запрос DaData.'));}
    }
    return <Stack spacing={2}>
        <Typography variant="h6">Справочники и проверка данных</Typography>
        <TextField select label="Что нужно найти или проверить" value={operation} disabled={state.isLoading} onChange={event => {setOperation(event.target.value); setResult(undefined); setError('');}}>
            {operations.map(item => <MenuItem key={item.id} value={item.id}>{item.title}</MenuItem>)}
        </TextField>
        {selected?.requiresSecret && !canClean && <Alert severity="info">Для этого метода администратору нужно указать секретный ключ DaData в разделе «Настройки».</Alert>}
        {geo ? <Stack direction={{xs: 'column', sm: 'row'}} gap={1}><TextField label="Широта" type="number" value={lat} inputProps={{min: -90, max: 90, step: 'any'}} helperText="От −90 до 90" onChange={event => setLat(event.target.value)}/><TextField label="Долгота" type="number" value={lon} inputProps={{min: -180, max: 180, step: 'any'}} helperText="От −180 до 180" onChange={event => setLon(event.target.value)}/></Stack>
            : operation === 'stat/daily' ? <TextField type="date" label="Дата статистики" InputLabelProps={{shrink: true}} value={date} onChange={event => setDate(event.target.value)}/>
            : !profile && <TextField multiline={clean} minRows={clean ? 3 : 1} label={operation === 'clean' ? 'ФИО | дата рождения | адрес | телефон | email | паспорт' : clean ? 'Данные для проверки — по одной записи на строку' : operation === 'iplocate/address' ? 'IP-адрес' : 'Название, код или значение для поиска'} value={query} onChange={event => setQuery(event.target.value)} inputProps={{maxLength: 10000}}/>}
        {!clean && !profile && operation !== 'iplocate/address' && <TextField type="number" label="Количество результатов" value={count} onChange={event => setCount(Number(event.target.value))} inputProps={{min: 1, max: operation === 'findById/party' ? 300 : 20}} sx={{maxWidth: 230}}/>}
        {clean && <Typography variant="caption" color="text.secondary">Стандартизация расходует средства на балансе DaData.</Typography>}
        {needsCount && !validCount && <Alert severity="warning">Укажите целое количество результатов от 1 до {operation === 'findById/party' ? 300 : 20}.</Alert>}
        <Button variant="contained" disabled={!configured || !selected || state.isLoading || (!!selected?.requiresSecret && !canClean) || (geo && !validGeo) || (needsCount && !validCount) || (!geo && !profile && !query.trim())} onClick={() => void run()} sx={{alignSelf: 'flex-start'}}>{state.isLoading ? <CircularProgress size={22}/> : 'Выполнить'}</Button>
        {error && <Alert severity="error">{error}</Alert>}
        {result !== undefined && <DataDetails value={result} name="Результат проверки"/>}
    </Stack>;
}
export default function CounterpartiesPage() {
    const [tab, setTab] = useState(0); const capabilities = useCounterpartyCapabilitiesQuery();
    return <MainDiv><Stack spacing={2}>
        <PageTitle>Проверка контрагентов</PageTitle>
        <Typography color="text.secondary">Найдите организацию, проверьте её реквизиты и сведения из реестров. Поиск доступен также при создании заказа и обработке файла для прихода.</Typography>
        {capabilities.isLoading && <CircularProgress/>}
        {capabilities.isError && <Alert severity="error" action={<Button onClick={() => void capabilities.refetch()}>Повторить</Button>}>Не удалось проверить подключение DaData.</Alert>}
        {capabilities.data && !capabilities.data.isConfigured && <Alert severity="info">DaData ещё не подключена. Администратору нужно задать API-ключ в разделе «Настройки» → «DaData — проверка контрагентов». <Button component={Link} to="/settings">Открыть настройки</Button></Alert>}
        <Tabs value={tab} onChange={(_, value) => setTab(value)}><Tab label="Организации"/><Tab label="Другие возможности DaData"/></Tabs>
        <Surface>{tab === 0 ? <CompanyPicker/> : capabilities.data ? <Tools operations={capabilities.data.operations} canClean={capabilities.data.canClean} configured={capabilities.data.isConfigured}/> : null}</Surface>
    </Stack></MainDiv>;
}
