import React, {useEffect, useRef, useState} from 'react';
import {Alert, Box, Button, CircularProgress, MenuItem, Stack, TextField, Typography} from '@mui/material';
import {getApiErrorMessage} from '../../api/errors';
import {companyIdentity, Counterparty, Country, useSearchCounterpartiesMutation} from './counterpartiesApi';
import CompanyCard from './CompanyCard';

export default function CompanyPicker({onSelect, initialQuery = '', initialCountry, selectLabel = 'Заполнить реквизиты'}: {
    onSelect?: (company: Counterparty) => void; initialQuery?: string; initialCountry?: Country; selectLabel?: string;
}) {
    const [country, setCountry] = useState<Country>(initialCountry || (/^\d{9}$/.test(initialQuery) ? 'BY' : 'RU'));
    const [query, setQuery] = useState(initialQuery); const [kpp, setKpp] = useState('');
    const [results, setResults] = useState<Counterparty[]>([]); const [selected, setSelected] = useState<Counterparty | null>(null);
    const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
    const [search] = useSearchCounterpartiesMutation(); const generation = useRef(0);
    useEffect(() => () => {generation.current++;}, []);
    function reset() {generation.current++; setBusy(false); setResults([]); setSelected(null); setError('');}
    async function run(company?: Counterparty) {
        const current = ++generation.current; setBusy(true); setError(''); setSelected(null);
        try {
            const text = company?.taxNumber || query.trim();
            const exact = !!company || (/^\d+$/.test(text) && (country === 'BY' ? text.length === 9 : country === 'KZ' ? text.length === 12 : [10,12,13,15].includes(text.length)));
            const found = await search({query: text, country, exact, kpp: company?.kpp || kpp || undefined, count: 20}).unwrap();
            if (current !== generation.current) return;
            if (company) {
                const matches = found.filter(item => !company.kpp || item.kpp === company.kpp);
                if (matches.length === 1) setSelected(matches[0]);
                else {setResults(matches); setError(matches.length ? 'Выберите конкретное подразделение.' : 'Организация больше не найдена. Повторите поиск.');}
            } else {setResults(found); if (!found.length) setError('Организации не найдены. Проверьте страну и запрос.');}
        } catch (failure) {if (current === generation.current) setError(getApiErrorMessage(failure, 'Не удалось выполнить поиск в DaData.'));}
        finally {if (current === generation.current) setBusy(false);}
    }
    return <Stack spacing={2}>
        <Stack direction={{xs: 'column', sm: 'row'}} gap={1}>
            <TextField select size="small" label="Страна" value={country} onChange={event => {reset(); setCountry(event.target.value as Country); setKpp('');}} sx={{minWidth: 150}}>
                <MenuItem value="RU">Россия</MenuItem><MenuItem value="BY">Беларусь</MenuItem><MenuItem value="KZ">Казахстан</MenuItem>
            </TextField>
            <TextField fullWidth size="small" label={country === 'BY' ? 'УНП или название' : country === 'KZ' ? 'БИН или название' : 'ИНН, ОГРН, название или руководитель'} value={query} inputProps={{maxLength: 300}}
                onChange={event => {reset(); setQuery(event.target.value);}} onKeyDown={event => {if (event.key === 'Enter') {event.preventDefault(); void run();}}}/>
            {country === 'RU' && <TextField size="small" label="КПП филиала" value={kpp} inputProps={{maxLength: 9}} onChange={event => {reset(); setKpp(event.target.value);}} sx={{minWidth: 140}}/>}
            <Button type="button" variant="contained" disabled={busy || query.trim().length < 2} onClick={() => void run()}>{busy ? <CircularProgress size={20}/> : 'Найти'}</Button>
        </Stack>
        {error && <Alert severity="warning">{error}</Alert>}
        {results.length > 0 && !selected && <Stack gap={1}>{results.map((item, index) => <Box key={`${item.taxNumber}.${item.kpp}.${index}`} sx={{p: 1.5, border: '1px solid', borderColor: 'divider', borderRadius: 2}}>
            <Typography fontWeight={600}>{item.name}</Typography><Typography variant="body2" color="text.secondary">{item.taxNumber}{item.kpp ? ` / ${item.kpp}` : ''} · {item.address}</Typography>
            <Button type="button" size="small" disabled={busy} onClick={() => void run(item)}>Проверить и выбрать</Button>
        </Box>)}</Stack>}
        {selected && <><CompanyCard company={selected}/><Stack direction="row" gap={1}>
            {onSelect && <Button type="button" variant="contained" onClick={() => onSelect({...selected, ...companyIdentity(selected)})}>{selectLabel}</Button>}
            <Button type="button" onClick={() => setSelected(null)}>К результатам поиска</Button>
        </Stack></>}
    </Stack>;
}
